def hold_in_default_warehouse(apps, schema_editor):
    """Every hold made so far was taken from the default warehouse of its kind;
    record that, so releasing and shipping it keep using that warehouse."""
    StockReservation = apps.get_model("orders", "StockReservation")
    Warehouse = apps.get_model("inventory", "Warehouse")
    defaults = {
        warehouse.kind: warehouse.id
        for warehouse in Warehouse.objects.filter(
            is_default=True, is_active=True, deleted_at__isnull=True
        )
    }
    for kind, warehouse_id in defaults.items():
        StockReservation.objects.filter(
            warehouse__isnull=True, variant__product__category__category_type=kind
        ).update(warehouse_id=warehouse_id)


